fn answer_of(turn: &AgentMessage, text: String) -> AgentMessage {
    let (api, provider, model, response_model, timestamp) = match turn {
        AgentMessage::Assistant {
            api,
            provider,
            model,
            response_model,
            timestamp,
            ..
        } => (api, provider, model, response_model.clone(), *timestamp),
        _ => (&String::new(), &String::new(), &String::new(), None, 0),
    };
    AgentMessage::Assistant {
        content: vec![Content::Text {
            text,
            text_signature: None,
        }],
        api: api.clone(),
        provider: provider.clone(),
        model: model.clone(),
        response_model,
        response_id: None,
        diagnostics: None,
        usage: Usage::unknown(),
        stop_reason: StopReason::Stop,
        deferred: None,
        error_message: None,
        raw_stop_reason: None,
        end_turn: None,
        timestamp,
    }
}

/// Invariant: the line never changes the JSON a structured reader parses out of the reply.
pub(crate) fn headed(summary: &str, text: &str) -> String {
    let (line, body) = (summary.trim(), text.trim_start());
    if line.is_empty() || body.starts_with(line) || serde_json::from_str::<Value>(body).is_ok() {
        return text.to_owned();
    }
    if body.is_empty() {
        return line.to_owned();
    }
    let reply = format!("{line}\n\n{text}");
    let same=[MASKED]).ok() == crate::schema::extract(text).ok();
    if same { reply } else { text.to_owned() }
}

